insert into public.products (id,name,category,wood_type,price,unit,grade,stock,image,description,dimensions) values
(1,'Balok Kayu Jati Perhutani Grade A','jati','Kayu Jati',12500000,'m³ (Meter Kubik)','Grade A (Tua & Kering Oven)',15,'https://images.unsplash.com/photo-1546484396-fb3fc6f95f98?auto=format&fit=crop&q=80&w=800','Kayu jati perhutani pilihan berumur di atas 40 tahun. Kering oven dengan kadar air rendah, stabil, tidak mudah muai susut. Sangat cocok untuk kusen mewah, pintu utama, dan mebel ukir kelas tinggi.','Tebal 6cm x Lebar 12cm x Panjang 4 Meter'),
(2,'Papan Kayu Mahoni Kiln Dry','mahoni','Kayu Mahoni',7800000,'m³ (Meter Kubik)','Grade A (Kiln Dry)',25,'https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&q=80&w=800','Papan mahoni pilihan yang telah melalui proses pengeringan oven (kiln dry). Tekstur pori-pori halus, mudah dicat duco maupun politur natural. Pilihan terbaik untuk meja, lemari, dan kitchen set.','Tebal 3cm x Lebar 20cm x Panjang 3 Meter'),
(3,'Kayu Meranti Merah Konstruksi','meranti','Kayu Meranti',6500000,'m³ (Meter Kubik)','Standard Bangunan',40,'https://images.unsplash.com/photo-1588854337236-6889d631faa8?auto=format&fit=crop&q=80&w=800','Kayu meranti merah asli Kalimantan. Kuat, lurus, dan memiliki daya tahan tinggi terhadap beban struktur bangunan. Sangat direkomendasikan untuk kuda-kuda atap, kaso, dan kusen.','Tebal 5cm x Lebar 10cm x Panjang 4 Meter'),
(4,'Kusen & Balok Kayu Kamper Samarinda','kamper','Kayu Kamper',9500000,'m³ (Meter Kubik)','Super Samarinda',18,'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&q=80&w=800','Kayu kamper samarinda dengan serat padat dan aroma khas yang dibenci serangga. Sangat stabil untuk pembuatan pintu panel, jendela, dan kusen bangunan komersial maupun hunian elit.','Tebal 6cm x Lebar 15cm x Panjang 3 Meter'),
(5,'Kayu Bengkirai Decking Outdoor','bengkirai','Kayu Bengkirai',11000000,'m³ (Meter Kubik)','Heavy Duty Outdoor',12,'https://images.unsplash.com/photo-1590381105924-c72589b9ef3f?auto=format&fit=crop&q=80&w=800','Kayu keras asal Kalimantan yang tahan cuaca ekstrem, panas, dan hujan. Sangat ideal untuk lantai kolam renang (decking), pagar taman, jembatan kayu, dan pergola.','Tebal 2.5cm x Lebar 10cm x Panjang 3 Meter'),
(6,'Papan Kayu Pinus / Jati Belanda','pinus','Kayu Pinus',4500000,'m³ (Meter Kubik)','Clear Face',50,'https://images.unsplash.com/photo-1538688525198-9b88f6f53126?auto=format&fit=crop&q=80&w=800','Kayu pinus pilihan tanpa mata mati (clear), warna cerah dengan serat alami yang estetik. Favorit untuk furniture bergaya industrial, scandinavian, dan rak dinding minimalis.','Tebal 2cm x Lebar 15cm x Panjang 2 Meter'),
(7,'Kayu Usuk / Kaso Meranti (5x7)','konstruksi','Kayu Meranti / Kruing',75000,'Batang (4 Meter)','Konstruksi Atap',150,'https://images.unsplash.com/photo-1600585152220-90363fe7e115?auto=format&fit=crop&q=80&w=800','Kaso atau usuk kayu keras untuk struktur rangka atap bangunan rumah dan gedung. Potongan lurus, presisi, dan kokoh menopang genteng.','Ukuran 5 x 7 cm x Panjang 4 Meter'),
(8,'Kayu Reng Atap (2x3 / 3x4)','konstruksi','Kayu Keras Lokal',35000,'Batang (4 Meter)','Konstruksi Atap',200,'https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&q=80&w=800','Reng kayu sebagai tumpuan pemasangan genteng keramik, beton, maupun metal roof. Kuat dan tahan lama.','Ukuran 3 x 4 cm x Panjang 4 Meter'),
(9,'Multiplek / Triplek 18mm Meranti','papan','Multiplek / Plywood',240000,'Lembar (122 x 244 cm)','Commercial Grade A',80,'https://images.unsplash.com/photo-1541888946425-d0fbb18f7293?auto=format&fit=crop&q=80&w=800','Triplek / multiplek tebal 18mm dengan lapisan face meranti. Sangat kuat untuk bahan dasar pembuatan kitchen set, lemari pakaian, backdrop TV, dan partisi.','Tebal 18 mm x Lebar 122 cm x Panjang 244 cm'),
(10,'Wood Pellet Biomassa Premium','wood-pellet','Wood Pellet',2500000,'Ton (1000 kg)','Premium Industrial Grade',50,'https://images.unsplash.com/photo-1587293852726-70cdb56c2866?auto=format&fit=crop&q=80&w=800','Pelet kayu (wood pellet) berkualitas tinggi untuk bahan bakar biomassa ramah lingkungan, boiler industri, dan pemanas. Nilai kalori tinggi, kadar abu rendah, dan bersih.','Diameter 6mm - 8mm (Kemasan Karung 25kg / Bulk)'),
(11,'Wood Pellet Kemasan 25 Kg (Eco-Friendly Fuel)','wood-pellet','Wood Pellet',75000,'Karung (25 kg)','Export Quality Standard',120,'https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?auto=format&fit=crop&q=80&w=800','Wood pellet siap pakai kemasan karung 25 kg. Sangat efisien untuk restoran, pemanas ruangan, kompor biomassa, dan industri skala menengah. Bersih, minim asap, dan kalori tinggi.','Diameter 8mm x Panjang 10-30mm (Kemasan 25 kg)')
